alert_traffic.query:
timeseries {
  usuarios_ativos = countDistinct(dt.frontend.user.active.estimated_count),
  sessoes_ativas = countDistinct(dt.frontend.session.active.estimated_count)
}, filter: {frontend.name == $Frontend and in(os.name, array($Plataforma)) and dt.rum.user_type == $TipoUsuario}, by: {os.name}

alert_errors.query:
timeseries {
  crashes = sum(dt.frontend.error.count, filter: {error.type == "crash"}),
  anrs = sum(dt.frontend.error.count, filter: {error.type == "anr"}),
  exceptions = sum(dt.frontend.error.count, filter: {error.type == "exception"})
}, filter: {frontend.name == $Frontend and in(os.name, array($Plataforma)) and dt.rum.user_type == $TipoUsuario}, by: {os.name}

action_latency.query:
timeseries {
  p50_ms = percentile(dt.frontend.user_action.duration, 50, rollup: avg),
  p75_ms = percentile(dt.frontend.user_action.duration, 75, rollup: avg),
  p95_ms = percentile(dt.frontend.user_action.duration, 95, rollup: avg)
}, filter: {frontend.name == $Frontend and in(os.name, array($Plataforma)) and dt.rum.user_type == $TipoUsuario}, by: {os.name}

request_latency.query:
timeseries {
  p50_ms = percentile(dt.frontend.request.duration, 50, rollup: avg),
  p75_ms = percentile(dt.frontend.request.duration, 75, rollup: avg),
  p95_ms = percentile(dt.frontend.request.duration, 95, rollup: avg)
}, filter: {frontend.name == $Frontend and in(os.name, array($Plataforma)) and dt.rum.user_type == $TipoUsuario}, by: {os.name}

error_rate.query:
timeseries {
  erros = sum(dt.frontend.error.count),
  requests = sum(dt.frontend.request.count)
}, filter: {frontend.name == $Frontend and in(os.name, array($Plataforma)) and dt.rum.user_type == $TipoUsuario}, by: {os.name}
| fieldsAdd taxa_erros_pct = 100.0 * erros[] / requests[]
| fieldsRemove erros, requests

timeout_rate.query:
timeseries {
  total = sum(dt.frontend.user_action.count),
  timeouts = sum(dt.frontend.user_action.count, filter: {user_action.complete_reason == "timeout"})
}, filter: {frontend.name == $Frontend and in(os.name, array($Plataforma)) and dt.rum.user_type == $TipoUsuario}, by: {os.name}
| fieldsAdd timeout_pct = 100.0 * timeouts[] / total[]
| fieldsRemove total, timeouts

crash_anr.query:
timeseries erros = sum(dt.frontend.error.count, scalar: true), filter: {frontend.name == $Frontend and in(os.name, array($Plataforma)) and dt.rum.user_type == $TipoUsuario}, by: {os.name, error.type}
| fields plataforma = os.name, tipo_erro = error.type, ocorrencias = erros
| sort ocorrencias desc

geo.query:
timeseries {
  usuarios = countDistinct(dt.frontend.user.active.estimated_count, scalar: true),
  sessoes = countDistinct(dt.frontend.session.active.estimated_count, scalar: true)
}, filter: {frontend.name == $Frontend and in(os.name, array($Plataforma)) and dt.rum.user_type == $TipoUsuario}, by: {os.name, geo.country.iso_code}
| fields plataforma = os.name, pais = geo.country.iso_code, usuarios, sessoes
| sort usuarios desc
| limit 30
